head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[date > M > getCurrentServerDate]<br/>서버의 현재 시간을 지정된 패턴으로 포맷하여 반환합니다.",
    "validation" : [
        "pattern(선택) 파라미터로 반환받을 날짜의 형식 패턴을 설정할 수 있어야 합니다.",
        "msaName(선택) 파라미터로 MSA 서버 이름을 설정할 수 있어야 합니다.",
        "pattern 생략 시 기본값 'yyyyMMdd' 형식으로 서버 날짜를 반환해야 합니다.",
        "pattern 에 시분초 포함 패턴(yyyyMMddHHmmssSSS) 설정 시 해당 형식으로 반환해야 합니다.",
        "msaName 미설정 시 포맷이 적용된 서버 날짜 문자열(String)을 직접 반환해야 합니다.",
        "msaName 설정 시 Promise 객체를 반환하며, resolve 값으로 포맷된 서버 날짜 문자열이 전달되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// pattern 별 정규식 맵
scwin.patternRegexMap = {
    "yyyyMMdd": /^\d{4}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])$/,
    "yyyyMMddHHmmssSSS": /^\d{4}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])([01]\d|2[0-3])([0-5]\d){2}\d{3}$/,
    "yyyyMMddHHmmss": /^\d{4}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])([01]\d|2[0-3])([0-5]\d){2}$/,
    "yyyy-MM-dd": /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/
};



// 반환값이 pattern 형식에 맞는지 검증하는 함수
scwin.validateResult = function (ret, pattern) {
    let actualPattern = (pattern === 'omit') ? 'yyyyMMdd' : pattern;
    let regex = scwin.patternRegexMap[actualPattern];
    if (!regex) {
        return "[검증] 지원하지 않는 패턴: " + actualPattern;
    }
    let isMatch = regex.test(ret);
    return "[검증] 패턴(" + actualPattern + ") 형식 일치 여부 → " + (isMatch ? "PASS" : "FAIL");
};



scwin.btn_getCurrentServerDate_onclick = function () {
    let pattern = par_pattern.getValue();
    let msaName = par_msaName.getValue();

    let ret;
    if (msaName === 'omit') {
        if (pattern === 'omit') {
            ret = WebSquare.date.getCurrentServerDate();
        } else {
            ret = WebSquare.date.getCurrentServerDate(pattern);
        }
        let validation = scwin.validateResult(ret, pattern);
        wf_body_bottom.getObj("scwin").setReturnValue(validation);
    } else {
        if (pattern === 'omit') {
            ret = WebSquare.date.getCurrentServerDate(undefined, msaName);
        } else {
            ret = WebSquare.date.getCurrentServerDate(pattern, msaName);
        }
        ret.then(function(serverTime) {
            let validation = scwin.validateResult(serverTime, pattern);
            wf_body_bottom.getObj("scwin").setReturnValue(validation);
        });
    }
}
